import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

/**
 * @param {Object} config
 * @param {Object} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container (position/rotation/scale will be applied by the adapter)
  const root = new Group();

  // Determine the atlas region – fallback to full texture if not provided
  const atlasInfo = config.atlas ?? {};
  const srcRect = atlasInfo.sourceRect ?? { x: 0, y: 0, width: 512, height: 320 };
  const atlasSize = atlasInfo.atlasSize ?? { width: srcRect.width, height: srcRect.height };

  const aspect = srcRect.width / srcRect.height;
  const planeWidth = 1 * aspect; // arbitrary unit height = 1
  const planeHeight = 1;

  // Geometry
  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  geometry.rotateX(-Math.PI / 2); // align plane upright (optional, depends on camera)

  // Basic node material (transparent sprite)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    depthTest: true,
    depthWrite: false,
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.frustumCulled = false; // ensures visibility even when tiny

  // Billboard – always face the camera
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };

  root.add(mesh);

  // Load texture asynchronously (function stays synchronous)
  let textureNode = null;
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    // Apply UV offset/repeat if an atlas region is defined
    if (atlasInfo && atlasInfo.sourceRect && atlasInfo.atlasSize) {
      const u = srcRect.x / atlasSize.width;
      const v = srcRect.y / atlasSize.height;
      const uScale = srcRect.width / atlasSize.width;
      const vScale = srcRect.height / atlasSize.height;
      tex.offset.set(u, v);
      tex.repeat.set(uScale, vScale);
    }

    textureNode = texture(tex);
    material.mapNode = textureNode;
    material.needsUpdate = true;
  });

  // No cinematic primitives to apply – placeholder for future extensions
  // (if config.cinematicPrimitives existed we would iterate here)

  // Event handlers placeholder (none defined in spec)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();

    // Dispose the loaded texture if it was created
    if (textureNode && textureNode.value) {
      textureNode.value.dispose();
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();
  };

  return root;
}
